    36→    public function getStudents(Schedule $schedule)
    37→    {
    38→        $lockService = app(ScheduleLockService::class);
    39→        $agreementService = app(ScheduleAgreementService::class);
    40→
    41→        if ($schedule->agreements()->count() === 0) {
    42→            $agreementService->syncForSchedule($schedule);
    43→        }
    44→
    45→        $students = Student::where('status', 'aktif')
    46→            ->when($schedule->cabang_id, fn($q) => $q->where('branch_id', $schedule->cabang_id))
    47→            ->orderBy('name')
    48→            ->get();
    49→
    50→        $existing = DB::table('absensi_siswas')
    51→            ->where('jadwal_id', $schedule->id)
    52→            ->pluck('status', 'siswa_id');
    53→
    54→        $agreements = $schedule->agreements()->get()->keyBy('student_id');
    55→
    56→        $attendanceLocked = $lockService->isAttendanceLocked($schedule);
    57→        $hasAttendance    = $lockService->hasAttendance($schedule);
    58→
    59→        return response()->json([
    60→            'success'            => true,
    61→            'students'           => $students,
    62→            'existing'           => $existing,
    63→            'attendance_locked'  => $attendanceLocked,
    64→            'has_attendance'     => $hasAttendance,
    65→            'schedule_locked'    => $lockService->isScheduleLocked($schedule),
    66→            'all_agreed'         => $agreementService->allStudentsAgreed($schedule),
