    71→    public function store(Request $request)
    72→    {
    73→        $schedule = Schedule::findOrFail($request->input('jadwal_id'));
    74→        $lockService = app(ScheduleLockService::class);
    75→        $agreementService = app(ScheduleAgreementService::class);
    76→
    77→        // Permanently locked once attendance already exists
    78→        if ($lockService->hasAttendance($schedule)) {
    79→            return response()->json([
    80→                'success' => false,
    81→                'message' => 'Absensi sudah pernah disimpan dan tidak dapat diubah.',
    82→            ], 422);
    83→        }
    84→
    85→        if ($lockService->isAttendanceLocked($schedule)) {
    86→            return response()->json([
    87→                'success' => false,
    88→                'message' => 'Absensi tidak dapat diubah karena jadwal pertemuan sudah selesai.',
    89→            ], 422);
    90→        }
    91→
    92→        if (! $agreementService->allStudentsAgreed($schedule)) {
    93→            return response()->json([
    94→                'success' => false,
    95→                'message' => 'Absensi hanya dapat diisi setelah guru dan siswa sepakat pada jadwal.',
    96→            ], 422);
    97→        }
    98→
    99→        $data = $request->validate([
   100→            'jadwal_id'              => 'required|exists:schedules,id',
   101→            'absensi'                => 'required|array|min:1',
   102→            'absensi.*.siswa_id'     => 'required|exists:students,id',
   103→            'absensi.*.status'       => 'required|in:hadir,izin,sakit,alpa',
   104→            'catatan'                => 'nullable|string',
   105→        ]);
   106→
   107→        $now = now();
   108→        $rows = [];
   109→        foreach ($data['absensi'] as $item) {
   110→            $rows[] = [
   111→                'jadwal_id'  => $data['jadwal_id'],
   112→                'siswa_id'   => $item['siswa_id'],
   113→                'status'     => $item['status'],
   114→                'catatan'    => $data['catatan'] ?? null,
   115→                'created_at' => $now,
   116→                'updated_at' => $now,
   117→            ];
   118→        }
   119→
   120→        // Insert only — never update existing records (permanent lock)
   121→        DB::table('absensi_siswas')->insertOrIgnore($rows);
   122→
   123→        // Mark schedule as selesai
   124→        $schedule->update(['status' => 'selesai']);
   125→
   126→        return response()->json(['success' => true, 'message' => 'Absensi berhasil disimpan dan dikunci!']);
   127→    }
