   129→    public function report(Request $request)
   130→    {
   131→        $teacher = Teacher::where('user_id', auth()->id())->first();
   132→
   133→        $report = DB::table('absensi_siswas as ab')
   134→            ->join('students as s', 's.id', '=', 'ab.siswa_id')
   135→            ->join('schedules as sch', 'sch.id', '=', 'ab.jadwal_id')
   136→            ->when($teacher, fn($q) => $q->where('sch.guru_id', $teacher->id))
   137→            ->when($request->bulan, fn($q) => $q->whereMonth('sch.tanggal', $request->bulan))
   138→            ->when($request->tahun, fn($q) => $q->whereYear('sch.tanggal', $request->tahun))
   139→            ->select('s.name', DB::raw("
   140→                SUM(CASE WHEN ab.status='hadir' THEN 1 ELSE 0 END) as hadir,
   141→                SUM(CASE WHEN ab.status='izin' THEN 1 ELSE 0 END) as izin,
   142→                SUM(CASE WHEN ab.status='sakit' THEN 1 ELSE 0 END) as sakit,
   143→                SUM(CASE WHEN ab.status='alpa' THEN 1 ELSE 0 END) as alpa,
   144→                COUNT(*) as total
   145→            "))
   146→            ->groupBy('s.name', 's.id')
   147→            ->get();
